changeSet.sql:
CREATE TABLE lbi_area_accesso (
                                  id        UUID PRIMARY KEY,
                                  area_id   UUID NOT NULL REFERENCES lbi_area(id) ON DELETE CASCADE,
                                  ruolo_id  UUID REFERENCES pg_lbi_system_roles(id) ON DELETE CASCADE,
                                  utente_id UUID REFERENCES pg_lbi_system_users(id) ON DELETE CASCADE,
                                  CONSTRAINT ck_area_accesso_uno CHECK ((ruolo_id IS NULL) <> (utente_id IS NULL))
);
CREATE UNIQUE INDEX ux_area_accesso_ruolo
    ON lbi_area_accesso (area_id, ruolo_id) WHERE ruolo_id IS NOT NULL;
CREATE UNIQUE INDEX ux_area_accesso_utente
    ON lbi_area_accesso (area_id, utente_id) WHERE utente_id IS NOT NULL;
